#include <torch/extension.h>
torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <vector>
#include <algorithm>

using namespace cute;

__device__ __forceinline__ float reduce_min_over_R(
    const float* __restrict__ ptr0, int R, int64_t inner64)
{
    int r = 1;
    float m0 = __ldg(ptr0);
    float m1 = m0, m2 = m0, m3 = m0, m4 = m0, m5 = m0, m6 = m0, m7 = m0;
    float m8 = m0, m9 = m0, m10 = m0, m11 = m0, m12 = m0, m13 = m0, m14 = m0, m15 = m0;
    const float* ptr = ptr0 + inner64;
    if (R >= 16) {
        const float* p1 = ptr0 + inner64;
        m1 = __ldg(p1);
        m2 = __ldg(p1 + inner64);
        m3 = __ldg(p1 + 2 * inner64);
        m4 = __ldg(p1 + 3 * inner64);
        m5 = __ldg(p1 + 4 * inner64);
        m6 = __ldg(p1 + 5 * inner64);
        m7 = __ldg(p1 + 6 * inner64);
        m8 = __ldg(p1 + 7 * inner64);
        m9 = __ldg(p1 + 8 * inner64);
        m10 = __ldg(p1 + 9 * inner64);
        m11 = __ldg(p1 + 10 * inner64);
        m12 = __ldg(p1 + 11 * inner64);
        m13 = __ldg(p1 + 12 * inner64);
        m14 = __ldg(p1 + 13 * inner64);
        m15 = __ldg(p1 + 14 * inner64);
        ptr = p1 + 15 * inner64;
        r = 16;
        int64_t step16 = 16 * inner64;
        #pragma unroll 1
        for (; r + 15 < R; r += 16) {
            m0 = fminf(m0, __ldg(ptr));
            m1 = fminf(m1, __ldg(ptr + inner64));
            m2 = fminf(m2, __ldg(ptr + 2 * inner64));
            m3 = fminf(m3, __ldg(ptr + 3 * inner64));
            m4 = fminf(m4, __ldg(ptr + 4 * inner64));
            m5 = fminf(m5, __ldg(ptr + 5 * inner64));
            m6 = fminf(m6, __ldg(ptr + 6 * inner64));
            m7 = fminf(m7, __ldg(ptr + 7 * inner64));
            m8 = fminf(m8, __ldg(ptr + 8 * inner64));
            m9 = fminf(m9, __ldg(ptr + 9 * inner64));
            m10 = fminf(m10, __ldg(ptr + 10 * inner64));
            m11 = fminf(m11, __ldg(ptr + 11 * inner64));
            m12 = fminf(m12, __ldg(ptr + 12 * inner64));
            m13 = fminf(m13, __ldg(ptr + 13 * inner64));
            m14 = fminf(m14, __ldg(ptr + 14 * inner64));
            m15 = fminf(m15, __ldg(ptr + 15 * inner64));
            ptr += step16;
        }
    } else if (R >= 8) {
        const float* p1 = ptr0 + inner64;
        m1 = __ldg(p1);
        m2 = __ldg(p1 + inner64);
        m3 = __ldg(p1 + 2 * inner64);
        m4 = __ldg(p1 + 3 * inner64);
        m5 = __ldg(p1 + 4 * inner64);
        m6 = __ldg(p1 + 5 * inner64);
        m7 = __ldg(p1 + 6 * inner64);
        ptr = p1 + 7 * inner64;
        r = 8;
        int64_t step8 = 8 * inner64;
        #pragma unroll 2
        for (; r + 7 < R; r += 8) {
            m0 = fminf(m0, __ldg(ptr));
            m1 = fminf(m1, __ldg(ptr + inner64));
            m2 = fminf(m2, __ldg(ptr + 2 * inner64));
            m3 = fminf(m3, __ldg(ptr + 3 * inner64));
            m4 = fminf(m4, __ldg(ptr + 4 * inner64));
            m5 = fminf(m5, __ldg(ptr + 5 * inner64));
            m6 = fminf(m6, __ldg(ptr + 6 * inner64));
            m7 = fminf(m7, __ldg(ptr + 7 * inner64));
            ptr += step8;
        }
    }
    float mlo = fminf(fminf(fminf(m0, m1), fminf(m2, m3)), fminf(fminf(m4, m5), fminf(m6, m7)));
    float mhi = fminf(fminf(fminf(m8, m9), fminf(m10, m11)), fminf(fminf(m12, m13), fminf(m14, m15)));
    float m = fminf(mlo, mhi);
    for (; r < R; ++r) {
        m = fminf(m, __ldg(ptr));
        ptr += inner64;
    }
    return m;
}
__global__ __launch_bounds__(256, 8) void min_reduce_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int outer, int R, int inner)
{
    int total = outer * inner;
    int stride = blockDim.x * gridDim.x;
    auto mY = make_tensor(
        make_gmem_ptr(Y),
        make_shape(outer, inner),
        make_stride((int64_t)inner, (int64_t)1)
    );
    int64_t inner64 = (int64_t)inner;
    // Thread coarsening: each thread computes FOUR independent output
    // reductions per outer loop iteration, issuing four independent
    // strided load chains back-to-back. This increases memory-level
    // parallelism (more outstanding loads in flight per thread),
    // which helps hide the latency of the strided reduction reads and
    // improves achieved DRAM bandwidth utilization for this
    // memory-bound kernel (the reduction stride equals `inner`, which
    // is odd, so aligned vector loads across r are not possible; deeper
    // MLP via 4-way coarsening is used instead).
    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total; idx += 4 * stride) {
        int idx1 = idx + stride;
        int idx2 = idx + 2 * stride;
        int idx3 = idx + 3 * stride;
        int o0 = idx / inner;
        int i0 = idx - o0 * inner;
        int64_t base0 = (int64_t)o0 * (int64_t)R * inner64 + (int64_t)i0;
        bool has1 = idx1 < total;
        bool has2 = idx2 < total;
        bool has3 = idx3 < total;
        int o1 = 0, i1 = 0, o2 = 0, i2 = 0, o3 = 0, i3 = 0;
        int64_t base1 = 0, base2 = 0, base3 = 0;
        if (has1) { o1 = idx1 / inner; i1 = idx1 - o1 * inner; base1 = (int64_t)o1 * (int64_t)R * inner64 + (int64_t)i1; }
        if (has2) { o2 = idx2 / inner; i2 = idx2 - o2 * inner; base2 = (int64_t)o2 * (int64_t)R * inner64 + (int64_t)i2; }
        if (has3) { o3 = idx3 / inner; i3 = idx3 - o3 * inner; base3 = (int64_t)o3 * (int64_t)R * inner64 + (int64_t)i3; }
        float m0 = reduce_min_over_R(X + base0, R, inner64);
        float m1 = has1 ? reduce_min_over_R(X + base1, R, inner64) : 0.0f;
        float m2 = has2 ? reduce_min_over_R(X + base2, R, inner64) : 0.0f;
        float m3 = has3 ? reduce_min_over_R(X + base3, R, inner64) : 0.0f;
        mY(o0, i0) = m0;
        if (has1) mY(o1, i1) = m1;
        if (has2) mY(o2, i2) = m2;
        if (has3) mY(o3, i3) = m3;
    }
}

torch::Tensor min_reduce_forward(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto x_c = x.contiguous();
    int ndim = x_c.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

    int64_t outer = 1;
    for (int i = 0; i < dim; ++i) outer *= x_c.size(i);
    int64_t R = x_c.size(dim);
    int64_t inner = 1;
    for (int i = dim + 1; i < ndim; ++i) inner *= x_c.size(i);

    std::vector<int64_t> out_sizes;
    out_sizes.reserve(ndim - 1);
    for (int i = 0; i < ndim; ++i) {
        if (i != dim) out_sizes.push_back(x_c.size(i));
    }

    auto y = torch::empty(out_sizes, x_c.options());

    int64_t total = outer * inner;
    const int threads = 256;
    const int coarsen = 4;
    // Size neededBlocks to account for the kernel's internal 4-way thread
    // coarsening so that blocks * threads * coarsen closely matches the
    // total number of output elements. Sizing based on threads alone (as
    // before) oversizes the grid relative to the coarsened workload,
    // leaving the final grid-stride wave very uneven across SMs/SMSPs/L1
    // slices (flagged by the profiler as an active-cycle imbalance).
    int64_t neededBlocks64 = (total + (int64_t)threads * coarsen - 1) / ((int64_t)threads * coarsen);
    int neededBlocks = (int)neededBlocks64;
    if (neededBlocks < 1) neededBlocks = 1;
    int device = 0;
    cudaGetDevice(&device);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    int numSMs = 0;
    cudaDeviceGetAttribute(&numSMs, cudaDevAttrMultiProcessorCount, device);
    int maxActiveBlocksPerSM = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &maxActiveBlocksPerSM, min_reduce_kernel, threads, 0);
    int occupancyBlocks = numSMs * maxActiveBlocksPerSM;
    if (occupancyBlocks < 1) occupancyBlocks = 1;
    int blocks = std::min(neededBlocks, occupancyBlocks);
    if (blocks < 1) blocks = 1;
    min_reduce_kernel<<<blocks, threads, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        (int)outer, (int)R, (int)inner
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "min_reduce_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["min_reduce_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs min reduction over a specific dimension using a
    custom CUTE-based CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce_forward(x, self.dim)

